FAR WScrollEx(ParamBlk FAR *parm)
{
   WHANDLE wh;
   Point pos;
   Rect rect;
   wh = _WOpenP(2, 2, 160, 320, WEVENT | CLOSE, WINDOW_SCHEME,
      (char *) 0, WO_SYSTEMBORDER);
  _WShow(wh);
   rect.top   = 40;
   rect.left   = 40;
   rect.bottom = 100;
   rect.right   = 100;
   for (pos.v = rect.top; pos.v < rect.bottom; pos.v += 6)
   {
